UPDATE tour.tickets
SET ticket_amount = #{ticketAmount}
WHERE id = (
    SELECT
    tp.tickets_id
    FROM public.payments p
    JOIN tour.ticket_payments tp ON tp.payments_id = p.id
    WHERE p.invoice_no = #{invoiceNo}
)

